# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TÜRKİYE\'DEKİ SU KAYNAKLARININ EKONOMİK VE ÇEVRESEL ETKİLERİ</text>\n  <rect x="25" y="50" width="205" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="127" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ekonomik Etkiler</text>\n  <text x="40" y="103" font-size="11" fill="#334155">• Tarımsal sulama (%74-77 pay)</text>\n  <text x="50" y="120" font-size="10.5" fill="#475569">GAP ve KOP ile ürün çeşitliliği</text>\n  <text x="40" y="145" font-size="11" fill="#334155">• Hidroelektrik (HES) ve</text>\n  <text x="50" y="162" font-size="10.5" fill="#475569">jeotermal enerji üretimi</text>\n  <text x="40" y="187" font-size="11" fill="#334155">• Deniz ticareti, balıkçılık, tuz</text>\n  <text x="50" y="204" font-size="10.5" fill="#475569">üretimi ve termal/kıyı turizmi</text>\n  <rect x="247" y="50" width="205" height="185" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Çevresel (Ekolojik) Etkiler</text>\n  <text x="262" y="103" font-size="11" fill="#334155">• Sulak alanlar (Ramsar alanları)</text>\n  <text x="272" y="120" font-size="10.5" fill="#475569">zengin biyoçeşitlilik barındırır.</text>\n  <text x="262" y="148" font-size="11" fill="#334155">• Göçmen kuşların konaklama</text>\n  <text x="272" y="165" font-size="10.5" fill="#475569">güzergahıdır (Manyas, Sultan S.).</text>\n  <text x="262" y="190" font-size="11" fill="#334155">• Mikroklima iklim alanları</text>\n  <text x="272" y="207" font-size="10.5" fill="#475569">ve alüvyal delta ovaları oluşturur.</text>\n  <rect x="470" y="50" width="205" height="185" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="572" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Sosyokültürel Etkiler</text>\n  <text x="485" y="103" font-size="11" fill="#334155">• Yerleşmelerin akarsu boyu</text>\n  <text x="495" y="120" font-size="10.5" fill="#475569">ve kıyılarda yoğunlaşması</text>\n  <text x="485" y="148" font-size="11" fill="#334155">• Hamam ve kaplıca kültürü,</text>\n  <text x="495" y="165" font-size="10.5" fill="#475569">rafting ve su sporları</text>\n  <text x="485" y="190" font-size="11" fill="#334155">• Tarihi medeniyet merkezleri</text>\n  <text x="495" y="207" font-size="10.5" fill="#475569">(Fırat-Dicle, Gediz, Menderes)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">POLİTİK ETKİLER: SINIR AŞAN SULAR VE BOĞAZLARIN JEOPOLİTİĞİ</text>\n  <rect x="35" y="50" width="300" height="185" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="185" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Türkiye\'nin Sınır Aşan Akarsuları</text>\n  <text x="50" y="105" font-size="11.5" font-weight="bold" fill="#1e40af">Türkiye\'den Doğup Yurt Dışına Çıkanlar:</text>\n  <text x="50" y="125" font-size="11" fill="#334155">• Fırat ve Dicle → Suriye, Irak (Basra Körfezi)</text>\n  <text x="50" y="145" font-size="11" fill="#334155">• Aras ve Kura → Ermenistan, Azerbaycan (Hazar)</text>\n  <text x="50" y="165" font-size="11" fill="#334155">• Çoruh → Gürcistan (Karadeniz)</text>\n  <text x="50" y="190" font-size="11.5" font-weight="bold" fill="#1e40af">Yurt Dışından Doğup Türkiye\'ye Girenler:</text>\n  <text x="50" y="210" font-size="11" fill="#334155">• Asi (Lübnan/Suriye) ve Meriç (Bulgaristan/Yunanistan)</text>\n  <rect x="365" y="50" width="300" height="185" rx="8" fill="#fef2f2" stroke="#ef4444"/>\n  <text x="515" y="75" text-anchor="middle" font-size="13" font-weight="bold" fill="#b91c1c">Su Politikaları ve Deniz Yetki Alanları</text>\n  <text x="380" y="105" font-size="11.5" fill="#334155">• İstanbul ve Çanakkale Boğazları (Montrö</text>\n  <text x="392" y="123" font-size="11" fill="#475569">Boğazlar Sözleşmesi) küresel stratejik su yoludur.</text>\n  <text x="380" y="150" font-size="11.5" fill="#334155">• KKTC Su Temin Projesi (&quot;Asrın Projesi&quot;):</text>\n  <text x="392" y="168" font-size="11" fill="#475569">Anamur Dragon Çayı\'ndan Kıbrıs\'a borularla su.</text>\n  <text x="380" y="195" font-size="11.5" fill="#334155">• Mavi Vatan: Karasuları, kıta sahanlığı ve</text>\n  <text x="392" y="213" font-size="11" fill="#475569">münhasır ekonomik bölge (MEB) haklarımız.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SU STRESİ, ÇEVRESEL TEHDİTLER VE SÜRDÜRÜLEBİLİR SU YÖNETİMİ</text>\n  <rect x="35" y="55" width="300" height="175" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="185" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Falkenmark Su Göstergesi ve Türkiye</text>\n  <text x="50" y="108" font-size="11" fill="#334155">• Kişi başı &gt; 1700 m³/yıl: Su zengini</text>\n  <text x="50" y="130" font-size="11" fill="#334155">• 1000 - 1700 m³/yıl: Su sıkıntısı (Su stresi)</text>\n  <text x="50" y="152" font-size="11" fill="#334155">• &lt; 1000 m³/yıl: Su fakiri</text>\n  <text x="50" y="182" font-size="11.5" font-weight="bold" fill="#b45309">Türkiye (~1300 m³/yıl): Su zengini değil,</text>\n  <text x="50" y="202" font-size="11.5" font-weight="bold" fill="#b45309">&quot;su stresi (su sıkıntısı)&quot; çeken ülkedir!</text>\n  <rect x="365" y="55" width="300" height="175" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="515" y="80" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Sürdürülebilir Koruma Çözümleri</text>\n  <text x="380" y="108" font-size="11" fill="#334155">• Vahşi (salma) sulama yerine damla ve</text>\n  <text x="392" y="126" font-size="11" fill="#475569">yağmurlama sulama sistemlerine geçilmesi</text>\n  <text x="380" y="150" font-size="11" fill="#334155">• Konya Havzası\'nda kaçak yer altı suyu</text>\n  <text x="392" y="168" font-size="11" fill="#475569">çekiminin ve obruk oluşumunun önlenmesi</text>\n  <text x="380" y="192" font-size="11" fill="#334155">• Atık su arıtımı, gri su ve yağmur suyu</text>\n  <text x="392" y="210" font-size="11" fill="#475569">hasadı ile müsilaj ve kirliliğin engellenmesi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
